/* ══════════════════════════════════════════════════════
   LexiLearn – Szómagyarázatok (V13.33)
   A japán szavak kézzel írt tudnivalói, a kana az azonosító (mint a szótárban).
     pos:   szófaj részletesen (ha a témakör-címkéből nem derül ki, pl. igecsoport)
     use:   Használat: mikor, kinek, milyen szerkezetben
     watch: Figyelj: a buktató (partikula, párja, azonos hangzású szó, rendhagyó alak)
     rel:   kapcsolódó szavak (a szótárban létező kanák)
   Nem minden szónak kell: ahol nincs mit mondani (pl. országnevek), a kártya
   „i” gombja az automatikus adatokat mutatja (témakör, szint, lecke, példa).
   A tests/word-notes.test.js ellenőrzi: létező szó, létező rokon, hossz, nincs emoji.
   1. adag: Dekiru 1–5. lecke, 2. adag: 6–10., 3. adag: 11–15., 4. adag: 16–20., 5. adag: 21–24. lecke.
   2. könyv: 6. adag: 25–29. lecke, 7. adag: 30–34., 8. adag: 35–39., 9. adag: 40–44., 10. adag: 45–48. lecke.
══════════════════════════════════════════════════════ */
